The peripheral role advertises GATT services through a `Server`. Open the GATT server once the adapter is on, before adding services.

```js
const { Server, Service, Characteristic } = require('bare-bluetooth-android')

const SERVICE_UUID = '01230000-0000-1000-8000-00805F9B34FB'

const server = new Server()

server.on('stateChange', (state) => {
  if (state !== 'on') return

  // The GATT server does not survive the adapter turning off, so reopen it and
  // add the services again on every transition to 'on'. close() is a no-op
  // when the server is not open, and open() throws when it already is.
  server.close()
  server.open()

  const characteristic = new Characteristic('01230001-0000-1000-8000-00805F9B34FB', {
    read: true,
    value: new Uint8Array([0x01])
  })

  server.addService(new Service(SERVICE_UUID, [characteristic]))
})

server.on('serviceAdd', () => {
  server.startAdvertising({ serviceUUIDs: [SERVICE_UUID] })
})

server.on('error', (err) => {
  console.error('server error:', err.code, err.message)
})
